import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Протокол и идемпотентность","description":"","frontmatter":{"pageId":"developers/protocol","contentRevision":5},"headers":[],"relativePath":"ru/developers/protocol.md","filePath":"ru/developers/protocol.md"}'),i={name:"ru/developers/protocol.md"};function l(n,e,s,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="протокол-и-идемпотентность" tabindex="-1">Протокол и идемпотентность <a class="header-anchor" href="#протокол-и-идемпотентность" aria-label="Permalink to &quot;Протокол и идемпотентность&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Протокол только растёт: добавляй поля с новыми номерами, сообщения, proto-файлы, ErrorCode и новые ServerEvent bodies. Не переиспользуй номера. events.proto импортирует feature proto; feature не должен импортировать events.proto, иначе цикл.</p><p>Мутации используют client_request_id. Неопределённый исход после обрыва повторяется с тем же id и исходным намерением через outbox; новый id означает новую операцию. Валидируй имена, размеры, пути, лимиты и допустимое состояние на границе. Rate/size refusal возвращает типизированный ErrorCode, не исключение наружу.</p><p>ProtocolVersion.Current сейчас 1 и меняется при несовместимом контракте, а не каждом релизе. Additive wire compatibility не означает, что старый клиент показывает новую функцию.</p><h2 id="mutation-contract" tabindex="-1">Контракт мутации: не только protobuf-поле <a class="header-anchor" href="#mutation-contract" aria-label="Permalink to &quot;Контракт мутации: не только protobuf-поле {#mutation-contract}&quot;">​</a></h2><p>Для новой мутации опиши вход, полномочия, предикат состояния, атомарный результат и повтор. Сохраняй client_request_id вместе с исходными данными до определённого ответа. Получение timeout не доказывает rollback сервера. Повтор с прежним id должен вернуть тот же смысл результата, а изменение payload под тем же id — не стать новой операцией.</p><p>Тестируй отказ по размеру/имени/праву до побочного эффекта, конкурентные запросы и повтор после commit до получения ответа. Для live row читается внутри LiveStateLock; проверка снаружи подвержена гонке.</p><p>Wire-совместимость, version UI и collection hash — разные проверки. Добавленный новый message не разрешает использовать неподдерживаемый клиентом UX без согласованного поведения.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Схема не является доказательством авторизации: права проверяются на сервере. Для influence ожидаемая версия/контекст и requestId защищают от запоздавших операций. Не журналируй полезную нагрузку с секретами ради отладки.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./storage">Хранилище и эскроу</a></li><li><a href="./client">Клиент, мод и live</a></li><li><a href="./../admins/api">Справочник REST API</a></li></ul>',14)])])}const m=a(i,[["render",l]]);export{h as __pageData,m as default};
